create table RB_INT_LAYER_RATE (IRL_SEQ_NO VARCHAR(50) not null  ,AGREEMENT_ID VARCHAR(50) null  ,INTERNAL_KEY INT null  ,CLIENT_NO VARCHAR(22) not null  ,ACCT_FIXED_RATE DECIMAL(15,8) null  ,ACCT_PERCENT_RATE DECIMAL(11,7) null  ,ACCT_SPREAD_RATE DECIMAL(15,8) null  ,NEAR_PERIOD VARCHAR(5) null  ,NEAR_PERIOD_TYPE VARCHAR(1) null  ,START_DATE TIMESTAMP(3) null  ,END_DATE TIMESTAMP(3) null  ,ACCR_DAYS INT null  ,ACCR_AMT DECIMAL(17,2) null  ,NEAR_AMT DECIMAL(17,2) null  ,INT_CLASS VARCHAR(5) null  ,INT_TYPE VARCHAR(5) null  ,REAL_RATE DECIMAL(15,8) null  ,ACTUAL_RATE DECIMAL(15,8) null  ,FLOAT_RATE DECIMAL(15,8) null  ,MONTH_BASIS VARCHAR(3) null  ,YEAR_BASIS VARCHAR(3) null  ,SYSTEM_ID VARCHAR(20) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,COMPANY VARCHAR(20) null  ,LAST_CHANGE_DATE TIMESTAMP(3) null  ,CREATE_TIMESTAMP VARCHAR(26) null  , primary key(IRL_SEQ_NO,CLIENT_NO));